font-size: 1.5em;
color: #111;
border-bottom: 2px solid #111;
padding-bottom: 8px;
}
.kiet-content p {
margin: 0 0 20px;
line-height: 1.9;
font-size: 1.05em;
word-break: keep-all;
}
/* 좌측 스티키 내비게이션 */
.kiet-navigator {
position: sticky;
top: 24px;
}
.kiet-navigator-inner {
border: 1px solid #e1e4e8;
padding: 20px;
background: #f8f9fa;
border-radius: 6px;
}
.kiet-navigator strong {
display: block;
margin-bottom: 14px;
font-size: 1.05em;
color: #1b1f23;
}
.kiet-navigator ul {
margin: 0;
padding-left: 18px;
}
.kiet-navigator li {
margin: 0 0 10px;
line-height: 1.5;
font-size: 0.95em;
}
.kiet-navigator a {
text-decoration: none;
color: #0366d6;
}
.kiet-navigator a:hover {
text-decoration: underline;
}
/* 하단 표준 인용 박스 */
.kiet-article-footer {
margin-top: 48px;
padding: 20px 24px;
background-color: #f4f6f9;
border-left: 4px solid #004085;
border-radius: 0 6px 6px 0;
}
.kiet-article-footer .citation-title {
margin: 0 0 8px 0;
font-weight: bold;
color: #004085;
font-size: 0.95em;
}
.kiet-article-footer .citation-text {
margin: 0;
font-size: 0.9em;
color: #495057;
line-height: 1.6;
}
@media (max-width: 900px) {
.kiet-content-wrap {
grid-template-columns: 1fr;
gap: 32px;
}
.kiet-navigator {
grid-column: 1;
grid-row: 1;
position: relative;
top: auto;
}
}
