display: inline-flex;
align-items: center;
justify-content: center;
width: 20px;
height: 20px;
font-size: 14px;
font-weight: bold;
color: #333;
background: #e1e4e8;
border-radius: 3px;
line-height: 1;
flex-shrink: 0;
margin-left: 6px;
}
.kiet-navigator summary:hover .kiet-toggle-btn {
background: #0366d6;
color: #fff;
}
.kiet-toggle-btn .plus { display: inline !important; }
.kiet-toggle-btn .minus { display: none !important; }
.kiet-navigator details[open] > summary .kiet-toggle-btn .plus { display: none !important; }
.kiet-navigator details[open] > summary .kiet-toggle-btn .minus { display: inline !important; }
.kiet-navigator ul ul {
margin: 6px 0 4px 12px;
padding-left: 10px;
border-left: 2px solid #e1e4e8;
}
.kiet-navigator ul ul li {
margin: 0 0 6px;
font-size: 0.88em;
}
@media (max-width: 900px) {
.kiet-content-wrap {
grid-template-columns: 1fr;
gap: 32px;
}
.kiet-navigator {
grid-column: 1;
grid-row: 1;
position: relative;
top: auto;
}
.kiet-navigator-inner {
max-height: none;
}
}
